def d(*args):
    return datetime(*args)


class Rules(unittest.TestCase):
    # "The first minute strictly after `after`"
    def test_strictly_after_when_on_match(self):
        self.assertEqual(next_run("30 10 * * *", d(2026, 10, 11, 10, 30)), d(2026, 10, 12, 10, 30))

    def test_seconds_and_microseconds_dropped_first(self):
        self.assertEqual(next_run("* * * * *", d(2026, 10, 11, 10, 0, 59, 999999)), d(2026, 10, 11, 10, 1))

    def test_truncation_does_not_skip_current_minute(self):
        self.assertEqual(next_run("5 10 * * *", d(2026, 10, 11, 10, 0, 30)), d(2026, 10, 11, 10, 5))

    # Five fields, single spaces
    def test_four_fields_rejected(self):
        with self.assertRaises(ValueError):
            next_run("0 0 * *", d(2026, 1, 1))

    def test_six_fields_rejected(self):
        with self.assertRaises(ValueError):
            next_run("0 0 * * * *", d(2026, 1, 1))

    def test_double_space_rejected(self):
        with self.assertRaises(ValueError):
            next_run("0  0 * * *", d(2026, 1, 1))

    def test_leading_and_trailing_space_rejected(self):
        with self.assertRaises(ValueError):
            next_run(" 0 0 * * *", d(2026, 1, 1))
        with self.assertRaises(ValueError):
            next_run("0 0 * * * ", d(2026, 1, 1))

    # Field ranges
    def test_minute_out_of_range(self):
        with self.assertRaises(ValueError):
            next_run("60 * * * *", d(2026, 1, 1))

    def test_hour_out_of_range(self):
        with self.assertRaises(ValueError):
            next_run("0 24 * * *", d(2026, 1, 1))

    def test_dom_zero_and_32_rejected(self):
        with self.assertRaises(ValueError):
            next_run("0 0 0 * *", d(2026, 1, 1))
        with self.assertRaises(ValueError):
            next_run("0 0 32 * *", d(2026, 1, 1))

    def test_month_zero_and_13_rejected(self):
        with self.assertRaises(ValueError):
            next_run("0 0 * 0 *", d(2026, 1, 1))
        with self.assertRaises(ValueError):
            next_run("0 0 * 13 *", d(2026, 1, 1))

    def test_dow_8_rejected(self):
        with self.assertRaises(ValueError):
            next_run("0 0 * * 8", d(2026, 1, 1))

    def test_range_bound_out_of_range(self):
        with self.assertRaises(ValueError):
            next_run("1-60 * * * *", d(2026, 1, 1))

    # Day of week: 7 is also Sunday
    def test_dow_7_is_sunday(self):
        # 2026-10-11 is a Sunday; next Sunday after Sunday 10:00 at 00:00 is 2026-10-18
        self.assertEqual(next_run("0 0 * * 7", d(2026, 10, 11, 10, 0)), d(2026, 10, 18))
        self.assertEqual(next_run("0 0 * * 0", d(2026, 10, 11, 10, 0)), d(2026, 10, 18))

    def test_range_ending_in_7(self):
        # 5-7 = Fri, Sat, Sun. From Sunday 2026-10-11 10:00 -> Mon 12 is excluded, Fri 16 next
        self.assertEqual(next_run("0 0 * * 5-7", d(2026, 10, 11, 10, 0)), d(2026, 10, 16))

    # Field syntaxes
    def test_plain_number(self):
        self.assertEqual(next_run("15 9 * * *", d(2026, 10, 11, 8, 0)), d(2026, 10, 11, 9, 15))

    def test_range(self):
        self.assertEqual(next_run("0 9-11 * * *", d(2026, 10, 11, 11, 0)), d(2026, 10, 12, 9, 0))

    def test_step(self):
        self.assertEqual(next_run("*/15 * * * *", d(2026, 10, 11, 10, 1)), d(2026, 10, 11, 10, 15))

    def test_range_step(self):
        self.assertEqual(next_run("10-30/10 * * * *", d(2026, 10, 11, 10, 0)), d(2026, 10, 11, 10, 10))
        self.assertEqual(next_run("10-30/10 * * * *", d(2026, 10, 11, 10, 30)), d(2026, 10, 11, 11, 10))

    def test_comma_list(self):
        self.assertEqual(next_run("0,30 * * * *", d(2026, 10, 11, 10, 0)), d(2026, 10, 11, 10, 30))

    def test_comma_list_mixing_forms(self):
        self.assertEqual(next_run("1,5-7,*/20 * * * *", d(2026, 10, 11, 10, 8)), d(2026, 10, 11, 10, 20))

    def test_star_inside_list(self):
        self.assertEqual(next_run("*,5 * * * *", d(2026, 10, 11, 10, 0)), d(2026, 10, 11, 10, 1))

    def test_step_zero_rejected(self):
        with self.assertRaises(ValueError):
            next_run("*/0 * * * *", d(2026, 1, 1))

    def test_step_on_plain_number_rejected(self):
        # grammar only allows */n and a-b/n
        with self.assertRaises(ValueError):
            next_run("5/10 * * * *", d(2026, 1, 1))

    def test_backwards_range_rejected(self):
        with self.assertRaises(ValueError):
            next_run("0 10-9 * * *", d(2026, 1, 1))

    def test_empty_list_element_rejected(self):
        with self.assertRaises(ValueError):
            next_run("1,,2 * * * *", d(2026, 1, 1))

    def test_garbage_rejected(self):
        for bad in ["a * * * *", "1- * * * *", "+5 * * * *", "1_0 * * * *", "1/2/3 * * * *", "1-2-3 * * * *"]:
            with self.assertRaises(ValueError, msg=bad):
                next_run(bad, d(2026, 1, 1))

    # Names
    def test_month_names_any_case(self):
        self.assertEqual(next_run("0 0 1 jan *", d(2026, 6, 1)), d(2027, 1, 1))
        self.assertEqual(next_run("0 0 1 Mar-May *", d(2026, 1, 1)), d(2026, 3, 1))

    def test_month_names_in_range(self):
        self.assertEqual(next_run("0 0 1 JAN-MAR *", d(2026, 3, 2)), d(2027, 1, 1))

    def test_day_names_any_case(self):
        self.assertEqual(next_run("0 0 * * fri", d(2026, 10, 11, 10, 0)), d(2026, 10, 16))

    def test_day_names_in_range(self):
        self.assertEqual(next_run("0 9 * * MON-FRI", d(2026, 10, 10, 10, 0)), d(2026, 10, 12, 9, 0))

    def test_name_out_of_its_field_rejected(self):
        with self.assertRaises(ValueError):
            next_run("0 0 * JAN *", d(2026, 1, 1)) if False else next_run("JAN * * * *", d(2026, 1, 1))
        with self.assertRaises(ValueError):
            next_run("0 0 * * MON-JAN", d(2026, 1, 1))

    # DOM / DOW interaction
    def test_dom_or_dow_when_both_restricted(self):
        # 0 0 13 * FRI: every 13th and every Friday. From 2026-10-11 (Sun): Fri 10-16 comes before 13th of Nov
        self.assertEqual(next_run("0 0 13 * FRI", d(2026, 10, 11)), d(2026, 10, 13))
        self.assertEqual(next_run("0 0 13 * FRI", d(2026, 10, 13)), d(2026, 10, 16))

    def test_dom_only_when_dow_star(self):
        self.assertEqual(next_run("0 0 13 * *", d(2026, 10, 14)), d(2026, 11, 13))

    def test_dow_only_when_dom_star(self):
        self.assertEqual(next_run("0 0 * * FRI", d(2026, 10, 14)), d(2026, 10, 16))

    def test_both_star(self):
        self.assertEqual(next_run("0 0 * * *", d(2026, 10, 11, 1, 0)), d(2026, 10, 12))

    # Naive times
    def test_naive_in_naive_out(self):
        r = next_run("0 0 * * *", d(2026, 10, 11, 1, 0))
        self.assertIsNone(r.tzinfo)

    # Beyond the docstring but implied: unsatisfiable and leap days
    def test_leap_day(self):
        self.assertEqual(next_run("0 0 29 2 *", d(2026, 10, 11)), d(2028, 2, 29))

    def test_never_fires_raises(self):
        with self.assertRaises(ValueError):
            next_run("0 0 31 2 *", d(2026, 1, 1))

    def test_end_of_datetime_range_raises_value_error(self):
        with self.assertRaises(ValueError):
            next_run("0 0 1 1 *", d(9999, 6, 1))


